int main() {
    std::vector<int> datos{1, 4, 8};
    double suma = 0.0;
    int cantidad = 0;
    for (int valor : datos) {
        if (valor >= 4) {
            suma += valor;
            ++cantidad;
        }
    }
    if (cantidad == 0) {
        std::cout << "Sin elegidos";
    } else {
        std::cout << suma / cantidad;
    }
    return 0;
}

